-- Wormholes:  the Sleeper sites, and the gas and ore sites of w-space, as they were in Crucible.
--  utils/wormholes/gen_sleeper_sites_sql.py writes this (the sources and picks are listed there)
--  - 47 combat anomalies, radar and magnetometric sites (C1-C6), 18 gas and 14 ore site dungeons
--  - faction Sleepers, difficulty = the w-space class.  AnomalyMgr spawns them in w-space only
--  - the Sleeper databanks and artifacts get the Sleeper loot families (datacores and decryptors;  ancient
--    salvage and relics).  the Talocan wrecks give ancient salvage
-- +migrate Up

-- site containers:  databanks are Sleeper data, artifacts Sleeper debris, the Talocan wrecks ancient salvage

-- +migrate Down
-- back to the F11 exploration families (20261011135000-F11-exploration.sql)
DELETE FROM expContainerFamily WHERE typeID BETWEEN 30516 AND 30530;
SELECT t.typeID,
  CASE WHEN t.typeName LIKE 'Sleeper%' THEN 5
       WHEN IFNULL(r.valueInt, r.valueFloat) = 13278 THEN 2
       WHEN IFNULL(r.valueInt, r.valueFloat) = 25863 THEN 3
       ELSE 1 END,
  CASE WHEN t.typeName LIKE 'Sleeper%' THEN 'Sleeper' ELSE '' END
FROM invTypes t
JOIN dgmTypeAttributes a ON a.typeID = t.typeID AND a.attributeID = 901
LEFT JOIN dgmTypeAttributes r ON r.typeID = t.typeID AND r.attributeID = 182
WHERE t.groupID = 306 AND t.typeID BETWEEN 30516 AND 30530;
DELETE FROM dunTriggerEvents WHERE eventID > 12000000 AND eventID < 13000000;
DELETE FROM dunTriggers WHERE triggerID > 12000000 AND triggerID < 13000000;
DELETE FROM dunSpawnGroupTypes WHERE spawnGroupID > 12000000 AND spawnGroupID < 13000000;
DELETE FROM dunSpawnGroups WHERE spawnGroupID > 12000000 AND spawnGroupID < 13000000;
DELETE FROM dunRoomObjects WHERE objectID > 12000000 AND objectID < 13000000;
DELETE FROM dunRooms WHERE roomID > 12000000 AND roomID < 13000000;
DELETE FROM dunDungeons WHERE dungeonID > 120000000 AND dungeonID < 121000000;
